    int is_huffman;
    int32_t len;

    if (*src >= src_end)
        return NULL;

    is_huffman = (**src & 0x80) != 0;
    if ((len = decode_int(src, src_end, 7)) == -1)
        return NULL;

    if (is_huffman) {
        uint8_t hflags = 0;
        if (*src + len > src_end)
            return NULL;
        if ((ret = decode_huffman(pool, *src, len, &hflags)) == NULL)
            return NULL;
