        } else {
            if (contains_invalid_field_value_char((char *)*src, len)) {
                *err_desc = soft_err_found_invalid_char_in_header_value;
            }
        }
        ret = alloc_buf(pool, len);
        memcpy(ret->base, *src, len);
        ret->base[len] = '\0';
    }
    *src += len;

    return ret;
}

